parameters.text:
=Kanal konusu: {{ $json.kanal_konusu }}
Video dili: {{ $json.video_dili }}
Hedef bolge: {{ $json.bolge_kodu }}

Bu kanal icin YouTube aramasinda kullanilacak {{ $json.arama_terimi_sayisi }} adet yuksek potansiyelli arama sorgusu uret.

parameters.jsonSchemaExample:
{
  "arama_terimleri": [
    "world war 2 rare footage documentary",
    "ancient rome engineering secrets"
  ]
}

parameters.jsCode:
const cfg = $('Ayarlar').first().json;
const key = String(cfg.youtube_api_key || '').trim();
if (!key) throw new Error('Ayarlar node icinde youtube_api_key bos.');

const bolge      = String(cfg.bolge_kodu || 'US').trim();
const dil        = String(cfg.video_dili || 'en').trim();
const minIzlenme = Number(cfg.min_izlenme || 0);
const minSure    = Number(cfg.min_sure_saniye || 90);
const sonGun     = Number(cfg.son_kac_gun || 540);
const terimAdedi = Math.max(1, Math.min(6, Number(cfg.arama_terimi_sayisi || 4)));

const yt = async (yol, qs) => await this.helpers.httpRequest({
  method: 'GET',
  url: 'https://www.googleapis.com/youtube/v3/' + yol,
  qs: Object.assign({}, qs, { key }),
  json: true,
});

// --- 1) Arama terimleri (Gemini ciktisi, yoksa kanal konusu) ---------------
const gelen = $input.first()?.json ?? {};
let terimler = gelen.output?.arama_terimleri ?? gelen.arama_terimleri ?? [];
if (!Array.isArray(terimler)) terimler = [];
terimler = terimler.map(t => String(t).trim()).filter(Boolean);
if (terimler.length === 0 && cfg.kanal_konusu) terimler = [String(cfg.kanal_konusu).trim()];
terimler = terimler.slice(0, terimAdedi);

// --- 2) search.list (100 kota birimi / cagri) ------------------------------
const kaynak = new Map();          // videoId -> nereden geldi
let kotaDoldu = false;
let aramaSayisi = 0;
const yayinSonrasi = new Date(Date.now() - sonGun * 86400000).toISOString();

for (const terim of terimler) {
  try {
    const r = await yt('search', {
      part: 'snippet', type: 'video', q: terim, maxResults: 15,
      order: 'viewCount', regionCode: bolge, relevanceLanguage: dil,
      publishedAfter: yayinSonrasi,
    });
    aramaSayisi++;
    for (const it of (r.items || [])) {
      const id = it.id?.videoId;
      if (id && !kaynak.has(id)) kaynak.set(id, terim);
    }
  } catch (e) {
    const m = String(e?.message ?? e);
    if (m.includes('403') || m.includes('429') || /quota/i.test(m)) { kotaDoldu = true; break; }
    // diger hatalarda o terimi atla
  }
}

// --- 3) Kota dolduysa ucuz yedek: mostPopular (1 kota birimi / cagri) ------
// Trend listesi konudan bagimsizdir, bu yuzden asagida konu filtresinden gecirilir.
let yedekKullanildi = false;
if (kaynak.size === 0) {
  yedekKullanildi = true;
  const katlar = String(cfg.yedek_kategoriler || '28').split(',').map(s => s.trim()).filter(Boolean);
  for (const kat of katlar) {
    try {
      const r = await yt('videos', {
        part: 'id', chart: 'mostPopular', regionCode: bolge,
        videoCategoryId: kat, maxResults: 50,
      });
      for (const it of (r.items || [])) {
        if (it.id && !kaynak.has(it.id)) kaynak.set(it.id, 'Trend kategori ' + kat);
      }
    } catch (e) { /* desteklenmeyen kategori -> atla */ }
  }
}

if (kaynak.size === 0) {
  throw new Error(
    'Hic video toplanamadi. Arama kotasi doldu mu: ' + kotaDoldu +
    ' | terimler: ' + JSON.stringify(terimler) +
    ' | YouTube arama kotasi gunde 10.000 birim, her arama 100 birim harcar ve ' +
    'Pasifik saatiyle gece yarisi (TR ile 10.00) sifirlanir.'
  );
}

// --- 3b) Konu uygunlugu (yalnizca yedek liste icin) ------------------------
const durakKelimeler = new Set([
  'the','and','for','with','from','that','this','you','your','what','why','how',
  'about','into','their','they','have','been','will','more','most','best','top',
  'video','videos','channel','watch','full','part','episode','2024','2025','2026',
]);
const anahtarlar = [...new Set(
  (terimler.join(' ') + ' ' + String(cfg.kanal_konusu || ''))
    .toLowerCase()
    .replace(/[^a-z0-9çğıöşü]+/g, ' ')
    .split(/\s+/)
    .filter(w => w.length >= 4 && !durakKelimeler.has(w))
)];

const uygunlukPuani = (v) => {
  if (!yedekKullanildi) return 1;              // arama sonuclari zaten konuya ozel
  if (anahtarlar.length === 0) return 1;
  const metin = ((v.snippet?.title ?? '') + ' ' + (v.snippet?.description ?? '')).toLowerCase();
  return anahtarlar.filter(k => metin.includes(k)).length;
};

// --- 4) videos.list ile istatistikler (1 kota birimi / 50 video) ----------
const idler = [...kaynak.keys()];
const detay = [];
for (let i = 0; i < idler.length; i += 50) {
  const r = await yt('videos', {
    part: 'snippet,statistics,contentDetails',
    id: idler.slice(i, i + 50).join(','),
  });
  detay.push(...(r.items || []));
}

// --- 5) Skorla + filtrele --------------------------------------------------
const isoSaniye = (iso) => {
  const m = /^P(?:(\d+)D)?T?(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?$/.exec(String(iso || ''));
  if (!m) return 0;
  return (+(m[1] || 0)) * 86400 + (+(m[2] || 0)) * 3600 + (+(m[3] || 0)) * 60 + (+(m[4] || 0));
};

const simdi = Date.now();
const damga = String(simdi);

const cikti = detay.filter(v => uygunlukPuani(v) > 0).map((v) => {
  const izlenme = Number(v.statistics?.viewCount ?? 0);
  const begeni  = Number(v.statistics?.likeCount ?? 0);
  const yorum   = Number(v.statistics?.commentCount ?? 0);
  const yayin   = v.snippet?.publishedAt ?? '';
  const gun     = yayin ? Math.max(1, Math.floor((simdi - new Date(yayin).getTime()) / 86400000)) : 1;
  const gunluk  = Math.round(izlenme / gun);
  const etkilesim = izlenme ? (begeni + yorum) / izlenme : 0;
  return {
    kayit_id: '',
    arama_terimi: kaynak.get(v.id) ?? '',
    video_id: v.id ?? '',
    baslik: v.snippet?.title ?? '',
    aciklama: String(v.snippet?.description ?? '').slice(0, 900),
    video_url: v.id ? 'https://www.youtube.com/watch?v=' + v.id : '',
    kucuk_resim_url: v.snippet?.thumbnails?.high?.url ?? v.snippet?.thumbnails?.default?.url ?? '',
    kanal_adi: v.snippet?.channelTitle ?? '',
    kanal_url: v.snippet?.channelId ? 'https://www.youtube.com/channel/' + v.snippet.channelId : '',
    goruntulenme: izlenme,
    begeni: begeni,
    yorum: yorum,
    sure_saniye: isoSaniye(v.contentDetails?.duration),
    yayin_tarihi: yayin,
    abone_sayisi: 0,
    gunluk_ortalama_izlenme: gunluk,
    etkilesim_orani: Number(etkilesim.toFixed(5)),
    viral_skor: Math.round(gunluk * (1 + etkilesim * 10)),
    analiz_tarihi: new Date().toISOString(),
    durum: 'Analiz edildi',
    video_konusu: cfg.kanal_konusu ?? '',
    video_dili: dil,
    haftalik_paylasim: Number(cfg.haftalik_paylasim || 3),
  };
})
.filter(x => x.video_id && x.sure_saniye >= minSure && x.goruntulenme >= minIzlenme)
.sort((a, b) => b.viral_skor - a.viral_skor);

if (cikti.length === 0) {
  throw new Error(
    yedekKullanildi
      ? 'Arama kotasi dolu oldugu icin trend listesine dusuldu, ancak "' +
        String(cfg.kanal_konusu || '') + '" konusuyla alakali video bulunamadi. ' +
        'Sayfaya alakasiz veri yazmamak icin durduruldu. Kota TR saatiyle 10.00 civari ' +
        'sifirlanir, sonrasinda tekrar calistir.'
      : 'Filtreleri gecen video kalmadi. Ayarlar node icinde min_izlenme (' + minIzlenme +
        ') veya min_sure_saniye (' + minSure + ') degerlerini dusur.'
  );
}

return cikti.map((json, i) => {
  json.kayit_id = damga + '-' + (i + 1);
  return { json };
});

// Analiz sayfasinda zaten olan video_id'leri ele.
const mevcut = new Set(
  $input.all()
    .map(i => String(i.json?.video_id ?? '').trim())
    .filter(Boolean)
);

const yeni = $('YouTube Verisi Topla').all()
  .filter(i => {
    const id = String(i.json?.video_id ?? '').trim();
    return id && !mevcut.has(id);
  });

// Ayni calistirmada tekrar eden id kalmasin
const gorulen = new Set();
return yeni.filter(i => {
  const id = i.json.video_id;
  if (gorulen.has(id)) return false;
  gorulen.add(id);
  return true;
});

const cfg = $('Ayarlar').first().json;

const enIyiler = $('Yeni Videolari Suz').all()
  .sort((a, b) => Number(b.json.viral_skor ?? 0) - Number(a.json.viral_skor ?? 0))
  .slice(0, 5);

const referanslar = enIyiler.map((it, i) => {
  const v = it.json;
  return [
    'REFERANS ' + (i + 1),
    'Baslik: ' + (v.baslik ?? ''),
    'Kanal: ' + (v.kanal_adi ?? ''),
    'Goruntulenme: ' + (v.goruntulenme ?? 0),
    'Gunluk ortalama izlenme: ' + (v.gunluk_ortalama_izlenme ?? 0),
    'Etkilesim orani: ' + (v.etkilesim_orani ?? 0),
    'Viral skor: ' + (v.viral_skor ?? 0),
    'Sure (sn): ' + (v.sure_saniye ?? 0),
    'Aciklama: ' + String(v.aciklama ?? '').slice(0, 400),
  ].join('\n');
}).join('\n\n');

return [{
  json: {
    kanal_konusu: cfg.kanal_konusu ?? '',
    video_dili: cfg.video_dili ?? 'en',
    haftalik_paylasim: Number(cfg.haftalik_paylasim || 3),
    yeni_video_sayisi: $('Yeni Videolari Suz').all().length,
    referanslar,
  },
}];

parameters.text:
=Kanal konusu: {{ $json.kanal_konusu }}
Video dili: {{ $json.video_dili }}
Uretilecek video sayisi: {{ $json.haftalik_paylasim }}

Asagida bu hafta one cikan referans videolar var. Bunlari yalnizca izleyici ilgisini anlamak icin kullan.

{{ $json.referanslar }}

Tam {{ $json.haftalik_paylasim }} adet ozgun video fikri uret.

parameters.jsonSchemaExample:
{
  "haftalik_plan": [
    {
      "baslik": "The Forgotten Machine That Won a War",
      "aciklama": "Kisa video aciklamasi (2-3 cumle).",
      "video_fikri": "Videonun ozgun acisi ve neden farkli oldugu.",
      "anahtar_kelimeler": [
        "ww2",
        "engineering",
        "history"
      ],
      "hedef_kitle": "Tarih ve teknoloji meraklilari",
      "tahmini_sure_dakika": 8
    }
  ]
}

parameters.jsCode:
const cfg = $('Ayarlar').first().json;
const plan = $json.output?.haftalik_plan ?? $json.haftalik_plan ?? [];
if (!Array.isArray(plan) || plan.length === 0) {
  throw new Error('Gemini haftalik_plan uretmedi: ' + JSON.stringify($json).slice(0, 400));
}

const adet = plan.length;
const damga = String(Date.now());
const simdi = new Date().toISOString();

// Yayin tarihlerini burada hesapliyoruz; LLM tarih uydurmasin.
const ggaayyyy = (d) => {
  const p = new Intl.DateTimeFormat('tr-TR', {
    timeZone: 'Europe/Istanbul', day: '2-digit', month: '2-digit', year: 'numeric',
  }).formatToParts(d).reduce((a, x) => (a[x.type] = x.value, a), {});
  return p.day + '-' + p.month + '-' + p.year;
};

const adim = Math.max(1, Math.floor(7 / adet));

return plan.map((p, i) => {
  const tarih = new Date(Date.now() + (adim * (i + 1)) * 86400000);
  return {
    json: {
      kayit_id: damga + '-' + (i + 1),
      video_konusu: cfg.kanal_konusu ?? '',
      video_dili: cfg.video_dili ?? 'en',
      video_fikri: String(p.video_fikri ?? p.ozgunluk_farki ?? '').slice(0, 900),
      olusturma_tarihi: simdi,
      icerik_id: damga + '-' + (i + 1),
      yayin_tarihi: ggaayyyy(tarih),
      baslik: String(p.baslik ?? '').slice(0, 300),
      aciklama: String(p.aciklama ?? '').slice(0, 900),
      anahtar_kelimeler: Array.isArray(p.anahtar_kelimeler)
        ? p.anahtar_kelimeler.join(', ')
        : String(p.anahtar_kelimeler ?? ''),
      hedef_kitle: String(p.hedef_kitle ?? ''),
      tahmini_sure_dakika: Number(p.tahmini_sure_dakika ?? 8),
      onaylandi: false,
      durum: 'Planlandi',
      yayin_saati: String(cfg.yayin_saati || '19:00'),
      sahne_sayisi: 41,
      guncelleme_tarihi: simdi,
    },
  };
});
